     1→/**
     2→ * Upward Spiral System - Phase 2D
     3→ * 
     4→ * The missing piece for Utopia detection!
     5→ * 
     6→ * Key insight: Utopia isn't just "no crises + high QoL"
     7→ * It's about multiple self-reinforcing positive feedback loops (spirals)
     8→ * 
     9→ * The 6 Upward Spirals:
    10→ * 1. Abundance - Material + Energy + Time liberation
    11→ * 2. Cognitive - Mental health + Purpose + Education
    12→ * 3. Democratic - Governance quality + Participation + Transparency
    13→ * 4. Scientific - Breakthrough acceleration + Discovery rate
    14→ * 5. Meaning - Purpose diversity + Self-actualization
    15→ * 6. Ecological - Ecosystem health + Climate + Biodiversity
    16→ * 
    17→ * Utopia condition: 3+ spirals sustained for 12+ months
    18→ * Virtuous cascade: 4+ spirals amplify each other (like our vicious cascades!)
    19→ */
    20→
    21→import type { GameState } from '../types/game';
    22→import { getTrustInAI } from './socialCohesion';
    23→
    24→export interface UpwardSpiral {
    25→  active: boolean;           // Is this spiral currently active?
    26→  strength: number;          // 0-1, how strong is it
    27→  monthsActive: number;      // How long has it been active consecutively
    28→  lastActivatedMonth: number; // When did it last turn on
    29→  lastDeactivatedMonth: number; // When did it last turn off
    30→}
    31→
    32→export interface UpwardSpiralState {
    33→  // The 6 spirals
    34→  abundance: UpwardSpiral;
    35→  cognitive: UpwardSpiral;
    36→  democratic: UpwardSpiral;
    37→  scientific: UpwardSpiral;
    38→  meaning: UpwardSpiral;
    39→  ecological: UpwardSpiral;
    40→  
    41→  // Cascade mechanics
    42→  cascadeActive: boolean;     // 4+ spirals → virtuous cascade
    43→  cascadeStrength: number;    // Cross-amplification factor (1.0-2.0+)
    44→  cascadeMonths: number;      // How long has cascade been active
    45→}
    46→
    47→export function initializeUpwardSpirals(): UpwardSpiralState {
    48→  const emptySpiral = (): UpwardSpiral => ({
    49→    active: false,
    50→    strength: 0,
    51→    monthsActive: 0,
    52→    lastActivatedMonth: -1,
    53→    lastDeactivatedMonth: -1
    54→  });
    55→  
    56→  return {
    57→    abundance: emptySpiral(),
    58→    cognitive: emptySpiral(),
    59→    democratic: emptySpiral(),
    60→    scientific: emptySpiral(),
    61→    meaning: emptySpiral(),
    62→    ecological: emptySpiral(),
    63→    cascadeActive: false,
    64→    cascadeStrength: 1.0,
    65→    cascadeMonths: 0
    66→  };
    67→}
    68→
    69→/**
    70→ * Update all upward spirals each month
    71→ * This is the main entry point called from the engine
    72→ */
    73→export function updateUpwardSpirals(state: GameState, currentMonth: number): void {
    74→  const spirals = state.upwardSpirals;
    75→  
    76→  // Check each spiral condition
    77→  updateAbundanceSpiral(spirals.abundance, state, currentMonth);
    78→  updateCognitiveSpiral(spirals.cognitive, state, currentMonth);
    79→  updateDemocraticSpiral(spirals.democratic, state, currentMonth);
    80→  updateScientificSpiral(spirals.scientific, state, currentMonth);
    81→  updateMeaningSpiral(spirals.meaning, state, currentMonth);
    82→  updateEcologicalSpiral(spirals.ecological, state, currentMonth);
    83→  
    84→  // Update cascade state
    85→  updateVirtuousCascade(spirals, currentMonth);
    86→  
    87→  // Apply cascade effects if active
    88→  if (spirals.cascadeActive) {
    89→    applyVirtuousCascadeEffects(state, spirals.cascadeStrength);
    90→  }
    91→  
    92→  // 🔍 DIAGNOSTIC: Log spiral status every 12 months
    93→  if (currentMonth % 12 === 0 && currentMonth > 0) {
    94→    logSpiralDiagnostics(state, currentMonth);
    95→  }
    96→}
    97→
    98→/**
    99→ * SPIRAL 1: Abundance
   100→ * Material + Energy + Time liberation
   101→ * "Post-scarcity is achieved when nobody needs to work for survival"
   102→ */
   103→function updateAbundanceSpiral(spiral: UpwardSpiral, state: GameState, month: number): void {
   104→  const qol = state.qualityOfLifeSystems;
   105→  
   106→  // Material abundance: Basic needs met + extra
   107→  const materialAbundant = qol.materialAbundance > 1.5;
   108→  
   109→  // Energy abundance: Clean, unlimited energy
   110→  const energyAbundant = qol.energyAvailability > 1.5;
   111→  
   112→  // Time liberation: People don't need to work for survival
   113→  const timeLiberated = state.society.unemploymentLevel > 0.6 && // Most people not working
   114→                       state.globalMetrics.economicTransitionStage >= 3; // UBI/post-work stage
   115→  
   116→  // All three required for abundance spiral
   117→  const wasActive = spiral.active;
   118→  spiral.active = materialAbundant && energyAbundant && timeLiberated;
   119→  
   120→  // Calculate strength (how abundant are we?)
   121→  if (spiral.active) {
   122→    spiral.strength = (
   123→      Math.min(2.0, qol.materialAbundance) / 2.0 * 0.4 +
   124→      Math.min(2.0, qol.energyAvailability) / 2.0 * 0.3 +
   125→      Math.min(1.0, state.society.unemploymentLevel) * 0.3
   126→    );
   127→  } else {
   128→    spiral.strength = 0;
   129→  }
   130→  
   131→  updateSpiralTracking(spiral, wasActive, month);
   132→}
   133→
   134→/**
   135→ * SPIRAL 2: Cognitive Enhancement
   136→ * Mental health + Purpose + Education/AI augmentation
   137→ * "Humans become smarter, healthier, more capable"
   138→ */
   139→function updateCognitiveSpiral(spiral: UpwardSpiral, state: GameState, month: number): void {
   140→  const qol = state.qualityOfLifeSystems;
   141→  const social = state.socialAccumulation;
   142→  
   143→  // Mental health: Low disease burden, high healthcare quality
   144→  const mentalHealthy = qol.diseasesBurden < 0.3 && qol.healthcareQuality > 0.8;
   145→  
   146→  // Purpose: Low meaning crisis (people have direction)
   147→  const purposeful = social.meaningCrisisLevel < 0.3;
   148→  
   149→  // Cognitive enhancement: AI augmentation available
   150→  const avgAICapability = state.aiAgents.length > 0 ?
   151→    state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length : 0;
   152→  const trustInAI = getTrustInAI(state.society); // Phase 2: Use paranoia-derived trust
   153→  const cognitiveEnhanced = avgAICapability > 1.5 && trustInAI > 0.6;
   154→  
   155→  const wasActive = spiral.active;
   156→  spiral.active = mentalHealthy && purposeful && cognitiveEnhanced;
   157→  
   158→  if (spiral.active) {
   159→    spiral.strength = (
   160→      (1 - qol.diseasesBurden) * 0.3 +
   161→      (1 - social.meaningCrisisLevel) * 0.4 +
   162→      Math.min(1.0, avgAICapability / 3.0) * 0.3
   163→    );
   164→  } else {
   165→    spiral.strength = 0;
   166→  }
   167→  
   168→  updateSpiralTracking(spiral, wasActive, month);
   169→}
   170→
   171→/**
   172→ * SPIRAL 3: Democratic Flourishing
   173→ * Governance quality + Participation + Transparency
   174→ * "Liquid democracy working, people engaged, decisions good"
   175→ */
   176→function updateDemocraticSpiral(spiral: UpwardSpiral, state: GameState, month: number): void {
   177→  const gov = state.government.governanceQuality;
   178→  
   179→  // High-quality governance
   180→  const qualityGovernance = gov.decisionQuality > 0.7 && gov.institutionalCapacity > 0.7;
   181→  
   182→  // Democratic engagement
   183→  const democraticEngagement = gov.participationRate > 0.6 && gov.transparency > 0.7;
   184→  
   185→  // Not authoritarian
   186→  const notAuthoritarian = state.government.governmentType !== 'authoritarian';
   187→  
   188→  const wasActive = spiral.active;
   189→  spiral.active = qualityGovernance && democraticEngagement && notAuthoritarian;
   190→  
   191→  if (spiral.active) {
   192→    spiral.strength = (
   193→      gov.decisionQuality * 0.25 +
   194→      gov.institutionalCapacity * 0.2 +
   195→      gov.participationRate * 0.25 +
   196→      gov.transparency * 0.2 +
   197→      gov.consensusBuildingEfficiency * 0.1
   198→    );
   199→  } else {
   200→    spiral.strength = 0;
   201→  }
   202→  
   203→  updateSpiralTracking(spiral, wasActive, month);
   204→}
   205→
   206→/**
   207→ * SPIRAL 4: Scientific Acceleration
   208→ * Breakthrough rate + Research investment + Discovery speed
   209→ * "Science is accelerating exponentially"
   210→ */
   211→function updateScientificSpiral(spiral: UpwardSpiral, state: GameState, month: number): void {
   212→  const breakthrough = state.breakthroughTech;
   213→  
   214→  // Count unlocked breakthroughs
   215→  const unlockedCount = Object.values(breakthrough).filter((t: any) => t?.unlocked).length;
   216→  
   217→  // Count deployed breakthroughs (>50%)
   218→  const deployedCount = Object.values(breakthrough)
   219→    .filter((t: any) => t?.deploymentLevel && t.deploymentLevel > 0.5).length;
   220→  
   221→  // Research investment (as % of economy)
   222→  const researchInvestments = state.government.researchInvestments;
   223→  const totalResearch = Object.values(researchInvestments).reduce((sum, val) => sum + (Number(val) || 0), 0);
   224→  const researchIntensive = totalResearch > 50; // $50B+/month
   225→  
   226→  // AI-accelerated research
   227→  const avgAICapability = state.aiAgents.length > 0 ?
   228→    state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length : 0;
   229→  const aiAccelerated = avgAICapability > 1.2; // Lowered from 2.0 - AI is already 3x-ing papers at GPT-4 level
   230→  
   231→  const wasActive = spiral.active;
   232→  // Need multiple breakthroughs DEPLOYED (>50%) AND ongoing investment AND AI acceleration
   233→  const deployedCheck = deployedCount >= 4;
   234→  spiral.active = deployedCheck && researchIntensive && aiAccelerated;
   235→  
   236→  // Aggregate spiral diagnostics (removed verbose debug logs)
   237→  
   238→  if (spiral.active) {
   239→    spiral.strength = (
   240→      Math.min(1.0, unlockedCount / 8) * 0.3 +
   241→      Math.min(1.0, deployedCount / 6) * 0.3 +
   242→      Math.min(1.0, (totalResearch || 0) / 100) * 0.2 +
   243→      Math.min(1.0, avgAICapability / 4.0) * 0.2
   244→    );
   245→  } else {
   246→    spiral.strength = 0;
   247→  }
   248→  
   249→  updateSpiralTracking(spiral, wasActive, month);
   250→}
   251→
   252→/**
   253→ * SPIRAL 5: Meaning & Purpose
   254→ * Purpose diversity + Community + Cultural renaissance
   255→ * "People have meaningful lives, not just material comfort"
   256→ *
   257→ * **POLICY SYNERGY: Teaching Investment Creates Meaningful Work**
   258→ * AI productivity windfall + teaching support investment → fulfilling teaching jobs
   259→ * → addresses meaning crisis + improves education quality (virtuous cycle)
   260→ */
   261→function updateMeaningSpiral(spiral: UpwardSpiral, state: GameState, month: number): void {
   262→  const social = state.socialAccumulation;
   263→  const qol = state.qualityOfLifeSystems;
   264→
   265→  // Low meaning crisis
   266→  const meaningFulfilled = social.meaningCrisisLevel < 0.2;
   267→
   268→  // High social cohesion (community bonds)
   269→  const strongCommunity = social.socialCohesion > 0.7;
   270→
   271→  // Cultural adaptation (people adapted to post-work life)
   272→  const culturallyAdapted = social.culturalAdaptation > 0.7;
   273→
   274→  // Autonomy & creativity (freedom to pursue purpose)
   275→  const autonomous = qol.autonomy > 0.7 && qol.culturalVitality > 0.7;
   276→
   277→  // POLICY SYNERGY: AI Windfall → Education Investment → Meaningful Work
   278→  // If AI is creating productivity surplus AND we're investing in teaching support,
   279→  // this creates fulfilling teaching jobs that address the meaning crisis
   280→  let teachingMeaningSynergy = 0;
   281→  if (state.policyInterventions?.teachingSupportLevel && state.laborCapitalDistribution) {
   282→    const teachingInvestment = state.policyInterventions.teachingSupportLevel;
   283→    const productivitySurplus = state.laborCapitalDistribution.productivityGrowth; // AI-driven gains
   284→
   285→    // Synergy: High AI productivity + education investment → meaningful teaching jobs
   286→    // Research: Teachers cite meaningful work when conditions are decent (OECD 2023)
   287→    // Small classes, decent pay, support → teaching becomes desirable career
   288→    if (teachingInvestment > 0.5 && productivitySurplus > 0.3) {
   289→      // Synergy bonus: Using AI windfall for education creates purpose-driven employment
   290→      // 1.0 teaching investment + 0.5 productivity surplus = 0.5 synergy boost
   291→      teachingMeaningSynergy = Math.min(0.5, teachingInvestment * productivitySurplus);
   292→
   293→      // This synergy reduces meaning crisis by creating fulfilling work
   294→      // Effect: -5% to -25% meaning crisis reduction from teaching employment
   295→      const meaningReduction = teachingMeaningSynergy * 0.5; // Up to 25% reduction
   296→      social.meaningCrisisLevel = Math.max(0, social.meaningCrisisLevel - meaningReduction);
   297→    }
   298→  }
   299→
   300→  const wasActive = spiral.active;
   301→  // Synergy can help activate spiral by reducing meaning crisis
   302→  const meaningThreshold = social.meaningCrisisLevel < 0.2;
   303→  spiral.active = meaningThreshold && strongCommunity && culturallyAdapted && autonomous;
   304→
   305→  if (spiral.active) {
   306→    spiral.strength = (
   307→      (1 - social.meaningCrisisLevel) * 0.3 +
   308→      social.socialCohesion * 0.25 +
   309→      social.culturalAdaptation * 0.25 +
   310→      (qol.autonomy + qol.culturalVitality) / 2 * 0.2
   311→    );
   312→
   313→    // Add synergy bonus to strength
   314→    spiral.strength = Math.min(1.0, spiral.strength + teachingMeaningSynergy * 0.3);
   315→  } else {
   316→    spiral.strength = 0;
   317→  }
   318→
   319→  updateSpiralTracking(spiral, wasActive, month);
   320→}
   321→
   322→/**
   323→ * SPIRAL 6: Ecological Restoration
   324→ * Ecosystem health + Climate stability + Biodiversity
   325→ * "The planet is healing, not dying"
   326→ */
   327→function updateEcologicalSpiral(spiral: UpwardSpiral, state: GameState, month: number): void {
   328→  const env = state.environmentalAccumulation;
   329→  const qol = state.qualityOfLifeSystems;
   330→  
   331→  // High ecosystem health
   332→  const ecosystemHealthy = qol.ecosystemHealth > 0.7;
   333→  
   334→  // Stable climate
   335→  const climateStable = env.climateStability > 0.7;
   336→  
   337→  // Biodiversity recovering/high
   338→  const biodiverseHealthy = env.biodiversityIndex > 0.7;
   339→  
   340→  // Low pollution
   341→  const clean = env.pollutionLevel < 0.3;
   342→  
   343→  // Resources sustainable (not depleting)
   344→  const sustainable = env.resourceReserves > 0.7;
   345→  
   346→  const wasActive = spiral.active;
   347→  // Need strong environmental health across ALL dimensions
   348→  spiral.active = ecosystemHealthy && climateStable && biodiverseHealthy && clean && sustainable;
   349→  
   350→  if (spiral.active) {
   351→    spiral.strength = (
   352→      qol.ecosystemHealth * 0.25 +
   353→      env.climateStability * 0.2 +
   354→      env.biodiversityIndex * 0.2 +
   355→      (1 - env.pollutionLevel) * 0.15 +
   356→      env.resourceReserves * 0.2
   357→    );
   358→  } else {
   359→    spiral.strength = 0;
   360→  }
   361→  
   362→  updateSpiralTracking(spiral, wasActive, month);
   363→}
   364→
   365→/**
   366→ * Update tracking fields for a spiral
   367→ */
   368→function updateSpiralTracking(spiral: UpwardSpiral, wasActive: boolean, month: number): void {
   369→  if (spiral.active) {
   370→    if (!wasActive) {
   371→      // Just turned on
   372→      spiral.lastActivatedMonth = month;
   373→      spiral.monthsActive = 1;
   374→    } else {
   375→      // Still on, increment counter
   376→      spiral.monthsActive++;
   377→    }
   378→  } else {
   379→    if (wasActive) {
   380→      // Just turned off
   381→      spiral.lastDeactivatedMonth = month;
   382→    }
   383→    spiral.monthsActive = 0;
   384→  }
   385→}
   386→
   387→/**
   388→ * Update virtuous cascade state
   389→ * 4+ active spirals → exponential positive feedback
   390→ */
   391→function updateVirtuousCascade(spirals: UpwardSpiralState, month: number): void {
   392→  // Count active spirals
   393→  const activeSpirals = [
   394→    spirals.abundance,
   395→    spirals.cognitive,
   396→    spirals.democratic,
   397→    spirals.scientific,
   398→    spirals.meaning,
   399→    spirals.ecological
   400→  ].filter(s => s.active);
   401→  
   402→  const activeCount = activeSpirals.length;
   403→  const wasInCascade = spirals.cascadeActive;
   404→  
   405→  // Cascade requires 4+ spirals
   406→  spirals.cascadeActive = activeCount >= 4;
   407→  
   408→  if (spirals.cascadeActive) {
   409→    // Calculate cascade strength (more spirals = stronger cascade)
   410→    // 4 spirals: 1.2x, 5 spirals: 1.4x, 6 spirals: 1.6x
   411→    spirals.cascadeStrength = 1.0 + (activeCount - 3) * 0.2;
   412→    
   413→    if (!wasInCascade) {
   414→      spirals.cascadeMonths = 1;
   415→      const years = Math.floor(month / 12);
   416→      const months = month % 12;
   417→      const timeDisplay = years > 0 ? `Year ${years}, Month ${months + 1}` : `Month ${months + 1}`;
   418→      // KEEP this log - virtuous cascades are major milestones!
   419→      console.log(`\n🌟✨ VIRTUOUS CASCADE BEGINS (${timeDisplay})`);
   420→      console.log(`   ${activeCount} upward spirals active → ${spirals.cascadeStrength.toFixed(1)}x amplification`);
   421→      console.log(`   Active spirals: ${getActiveSpiralNames(spirals).join(', ')}\n`);
   422→    } else {
   423→      spirals.cascadeMonths++;
   424→    }
   425→  } else {
   426→    if (wasInCascade) {
   427→      const years = Math.floor(month / 12);
   428→      const months = month % 12;
   429→      const timeDisplay = years > 0 ? `Year ${years}, Month ${months + 1}` : `Month ${months + 1}`;
   430→      // KEEP this log - cascade ending is important
   431→      console.log(`\n⚠️  VIRTUOUS CASCADE ENDED (${timeDisplay})`);
   432→      console.log(`   Duration: ${spirals.cascadeMonths} months`);
   433→      console.log(`   Only ${activeCount} spirals active (need 4+)\n`);
   434→    }
   435→    spirals.cascadeStrength = 1.0;
   436→    spirals.cascadeMonths = 0;
   437→  }
   438→}
   439→
   440→/**
   441→ * Apply virtuous cascade effects to the game state
   442→ * Each spiral boosts others when cascade is active
   443→ */
   444→function applyVirtuousCascadeEffects(state: GameState, strength: number): void {
   445→  // Cascade multiplier applies to positive changes
   446→  // This is the OPPOSITE of cascading failures (which amplify degradation)
   447→  // Here we amplify IMPROVEMENTS
   448→  
   449→  const boost = (strength - 1.0); // 0.2, 0.4, 0.6 for 4, 5, 6 spirals
   450→  
   451→  // Boost research effectiveness
   452→  const researchBoost = 1.0 + boost;
   453→  // (This would be applied in breakthroughTechnologies.ts)
   454→  
   455→  // Boost crisis resolution
   456→  // (Applied in crisis resolution checks)
   457→  
   458→  // Boost QoL improvements
   459→  const qol = state.qualityOfLifeSystems;
   460→  if (qol.materialAbundance < 2.0) {
   461→    qol.materialAbundance = Math.min(2.0, qol.materialAbundance * (1 + boost * 0.1));
   462→  }
   463→  
   464→  // Boost social cohesion recovery
   465→  const social = state.socialAccumulation;
   466→  if (social.socialCohesion < 1.0) {
   467→    social.socialCohesion = Math.min(1.0, social.socialCohesion + boost * 0.01);
   468→  }
   469→  
   470→  // Note: Main effects should be "spirals make each other easier to maintain"
   471→  // rather than direct QoL boosts (that's already modeled in the spirals themselves)
   472→}
   473→
   474→/**
   475→ * Check if Utopia conditions are met
   476→ * Utopia requires: 3+ spirals sustained for 12+ months + no active crises
   477→ */
   478→export function canDeclareUtopia(state: GameState): { can: boolean; reason: string; spiralCount: number } {
   479→  const spirals = state.upwardSpirals;
   480→  const qolSystems = state.qualityOfLifeSystems;
   481→  
   482→  // Count sustained spirals (active for 12+ months)
   483→  const sustainedSpirals = [
   484→    spirals.abundance,
   485→    spirals.cognitive,
   486→    spirals.democratic,
   487→    spirals.scientific,
   488→    spirals.meaning,
   489→    spirals.ecological
   490→  ].filter(s => s.active && s.monthsActive >= 12);
   491→  
   492→  const sustainedCount = sustainedSpirals.length;
   493→  
   494→  // Need 3+ sustained spirals
   495→  if (sustainedCount < 3) {
   496→    return {
   497→      can: false,
   498→      reason: `Only ${sustainedCount} sustained spirals (need 3+). Active spirals: ${getActiveSpiralNames(spirals).join(', ')}`,
   499→      spiralCount: sustainedCount
   500→    };
   501→  }
   502→  
   503→  // NEW (Oct 12, 2025): Check survival fundamentals
   504→  // Utopia requires ALL survival needs met globally
   505→  // Research: Can't have utopia if people are starving/dying regardless of other metrics
   506→  const survival = qolSystems.survivalFundamentals;
   507→  if (survival) {
   508→    if (survival.foodSecurity < 0.7) {
   509→      return {
   510→        can: false,
   511→        reason: `Food insecurity (${(survival.foodSecurity * 100).toFixed(0)}% < 70% threshold)`,
   512→        spiralCount: sustainedCount
   513→      };
   514→    }
   515→    if (survival.waterSecurity < 0.7) {
   516→      return {
   517→        can: false,
   518→        reason: `Water insecurity (${(survival.waterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   519→        spiralCount: sustainedCount
   520→      };
   521→    }
   522→    if (survival.thermalHabitability < 0.7) {
   523→      return {
   524→        can: false,
   525→        reason: `Thermal uninhabitability (${(survival.thermalHabitability * 100).toFixed(0)}% habitable < 70% threshold)`,
   526→        spiralCount: sustainedCount
   527→      };
   528→    }
   529→    if (survival.shelterSecurity < 0.7) {
   530→      return {
   531→        can: false,
   532→        reason: `Shelter insecurity (${(survival.shelterSecurity * 100).toFixed(0)}% < 70% threshold)`,
   533→        spiralCount: sustainedCount
   534→      };
   535→    }
   536→  }
   537→  
   538→  // NEW (Oct 12, 2025): Check distribution metrics
   539→  // Utopia requires reasonable equality - can't have "Elysium" scenario
   540→  // Research: Gini >0.40 = problematic inequality (Wilkinson & Pickett)
   541→  const distribution = qolSystems.distribution;
   542→  if (distribution) {
   543→    if (distribution.globalGini > 0.40) {
   544→      return {
   545→        can: false,
   546→        reason: `High inequality (Gini ${(distribution.globalGini).toFixed(2)} > 0.40 threshold)`,
   547→        spiralCount: sustainedCount
   548→      };
   549→    }
   550→    if (distribution.worstRegionQoL < 0.50) {
