/**
 * Flash War Escalation Phase - Fix #5
 *
 * Phase Order: After WarDeathPhase (TBD - likely ~28-29)
 *
 * Models flash war escalation from AI-enhanced autonomous weapons.
 * Implements three mechanics:
 * 1. Flash war risk check (5% per conflict/month when AI > 4.0)
 * 2. AI-mediated de-escalation (aligned high-cap AI can prevent)
 * 3. Circuit breaker development (3-month delay after first flash war)
 *
 * Research: ECFR (2024), Penn CERL (2024), UN Resolution 166-3
 */

import type { GameState } from '../../../types/game';
import type { PhaseContext, PhaseResult } from '../types';
import type { RNGFunction } from '../rng';
import {
  checkFlashWarRisk,
  applyFlashWarEffects,
  attemptAIDeEscalation,
  updateCircuitBreakers
} from '../../flashWarEscalation';

export function executeFlashWarEscalationPhase(
  state: GameState,
  rng: RNGFunction,
  context: PhaseContext
): PhaseResult {
  const logs: string[] = [];

  // STEP 1: Attempt AI-mediated de-escalation FIRST (prevents flash wars)
  if (state.conflictResolution.activeConflicts && state.conflictResolution.activeConflicts > 0) {
    const deescalationSuccess = attemptAIDeEscalation(state, rng);

    if (deescalationSuccess) {
      logs.push(`AI-mediated de-escalation prevented conflict escalation`);
      // De-escalation reduces activeConflicts
      state.conflictResolution.activeConflicts = Math.max(0, state.conflictResolution.activeConflicts - 1);
    }
  }

  // STEP 2: Check for flash war escalation (if conflicts still active)
  if (state.conflictResolution.activeConflicts && state.conflictResolution.activeConflicts > 0) {
    const flashWarOccurs = checkFlashWarRisk(state, rng);

    if (flashWarOccurs) {
      applyFlashWarEffects(state);
      logs.push(`⚠️ FLASH WAR: Autonomous weapons escalated conflict at machine speed`);
      logs.push(`   War deaths multiplied by 2.5x before circuit breakers could engage`);
    }
  }

  // STEP 3: Update circuit breaker development
  updateCircuitBreakers(state);

  // Build result
  return {
    success: true,
    message: logs.length > 0 ? logs.join('\n') : 'Flash war phase complete (no escalation this month)',
    context: {
      ...context,
      flashWarChecked: true,
      flashWarOccurred: logs.some(l => l.includes('FLASH WAR')),
      deescalationAttempted: logs.some(l => l.includes('de-escalation'))
    }
  };
}

